mapper.select:
SELECT d.*, u.username, u.avatar, (SELECT COUNT(*) FROM diary_like WHERE diary_id = d.id AND user_id = #{currentUserId}) > 0 AS likedByCurrentUser, (SELECT COUNT(*) FROM diary_favorite WHERE diary_id = d.id AND user_id = #{currentUserId}) > 0 AS favoritedByCurrentUser FROM diary d JOIN sys_user u ON d.user_id = u.id WHERE d.permission = 2 AND d.user_id IN
#{id}
ORDER BY d.create_time DESC
